Vec3 sub(Vec3 a, Vec3 b) { return (Vec3){a.x-b.x, a.y-b.y, a.z-b.z}; }
Vec3 mul(Vec3 a, float t) { return (Vec3){a.x*t, a.y*t, a.z*t}; }
float dot(Vec3 a, Vec3 b) { return a.x*b.x + a.y*b.y + a.z*b.z; }
float len(Vec3 a) { return sqrtf(dot(a, a)); }
Vec3 norm(Vec3 a) { float l = len(a); return l > 1e-4 ? mul(a, 1.0f/l) : a; }
Ray mkray(Vec3 o, Vec3 t) { Vec3 d = sub(t, o); float l = len(d); return (Ray){o, l > 1e-4 ? mul(d, 1.0f/l) : d}; }
Vec3 rayat(Ray r, float t) { return add(r.o, mul(r.d, t)); }
int sph(Sphere s, Ray r, Vec3 *n, float *t) {
  Vec3 oc = sub(r.o, s.p);
  float a = dot(r.d, r.d), b = 2*dot(oc, r.d), c = dot(oc, oc) - s.r*s.r, disc = b*b - 4*a*c;
  if (disc < 0) return 0;
  float tt = (-b - sqrtf(disc)) / (2*a);
  if (tt <= 1e-4) return 0;
  *n = norm(sub(rayat(r, tt), s.p)); *t = tt; return 1;
}
int pln(Plane p, Ray r, Vec3 *n, float *t) {
  float den = dot(p.n, r.d);
  if (fabsf(den) < 1e-4) return 0;
  float tt = (p.d - dot(p.n, r.o)) / den;
  if (tt <= 1e-4) return 0;
  *n = p.n; *t = tt; return 1;
}
Vec3 sky(Vec3 d) { d = norm(d); float t = 0.5f * (d.y + 1.0f); return add(mul((Vec3){1,1,1}, t), mul((Vec3){0.5f,0.7f,1}, 1-t)); }
int shd(Vec3 p, Vec3 ld, Sphere *ss, int ns, Plane *ps, int np) {
  Ray sr = mkray(p, add(p, ld));
  for(int i=0; i<ns; i++) { Vec3 nn; float tt; if(sph(ss[i], sr, &nn, &tt) && tt>1e-4 && tt<100) return 1; }
  for(int i=0; i<np; i++) { Vec3 nn; float tt; if(pln(ps[i], sr, &nn, &tt) && tt>1e-4 && tt<100) return 1; }
